ruleContent.content:
@js:
// 1. 提取 content 字段
var m = result.match(/"content":"([\s\S]*?)","uid"/);
var content = m ? m[1] : '';

// 2. 先反转义 JSON 特殊字符
content = content.replace(/\\u003C/g, '<')
                 .replace(/\\u003E/g, '>')
                 .replace(/\\u002F/g, '/')
                 .replace(/\\n/g, '\n')
                 .replace(/\\"/g, '"');

// 3. 提取所有 <p> 标签内容
var paras = content.match(/<p[^>]*>([\s\S]*?)<\/p>/g) || [];
var texts = [];
for (var i = 0; i < paras.length; i++) {
  var t = paras[i].replace(/<[^>]+>/g, '').trim();
  if (t) {
    texts.push(t);
  }
}

// 4. 拼接
var raw = texts.join('\n\n');

// 5. 解密
result = GetContentDecode(raw);

// 6. 判断内容长度，过短则拼接提示文本
if (result.length < 500) {
  result = result + "\n\n【请购买会员并在阅读登录账号!!!】";
}

ruleContent.title:
@js:
var m = result.match(/"title":"([^"]+)"/);
var title = m ? m[1] : '';
// 去掉书名前缀
var idx = title.indexOf('第');
if (idx > -1) {
  title = title.substring(idx);
}
// 去掉"在线免费阅读"及之后的内容
var endIdx = title.indexOf('在线免费阅读');
if (endIdx > -1) {
  title = title.substring(0, endIdx);
}
result = title.trim();

