mm.addEventListener("click",function(ev){ev.preventDefault();ev.stopPropagation();ev.stopImmediatePropagation();openLB(mm.src);},true);}var pipEl=document.getElementById("pip");var dragOn=false,dragMoved=false,pressT=null,dsx=0,dsy=0,dol=0,dot=0;if(pipEl){pipEl.addEventListener("touchstart",function(e){var t=e.touches[0];dsx=t.clientX;dsy=t.clientY;var r=pipEl.getBoundingClientRect();dol=r.left;dot=r.top;dragMoved=false;pressT=setTimeout(function(){dragOn=true;pipEl.classList.add("drag");},350);});pipEl.addEventListener("touchmove",function(e){if(!dragOn)return;e.preventDefault();var t=e.touches[0];if(Math.abs(t.clientX-dsx)>6||Math.abs(t.clientY-dsy)>6){dragMoved=true;}var w=pipEl.offsetWidth,h=pipEl.offsetHeight;var nx=Math.max(4,Math.min(window.innerWidth-w-4,dol+t.clientX-dsx));var ny=Math.max(4,Math.min(window.innerHeight-h-4,dot+t.clientY-dsy));pipEl.style.left=nx+"px";pipEl.style.top=ny+"px";pipEl.style.right="auto";});pipEl.addEventListener("touchend",function(){clearTimeout(pressT);if(dragOn&&dragMoved){suppressClick=true;}dragOn=false;pipEl.classList.remove("drag");});}';
